// InvoiceExportService.java (release 3 ngày trước)
Path exportMerged(List<Invoice> invoices) throws IOException {
    byte[] pdf = pdfRenderer.renderMerged(invoices);        // 1-9 MB tuỳ số hoá đơn
    Path tmp = Files.createTempFile("invoices-", ".pdf");
    try (var channel = FileChannel.open(tmp, StandardOpenOption.WRITE)) {
        channel.write(ByteBuffer.wrap(pdf));                // heap buffer, ghi một lần
    }
    return tmp;                                             // sau đó upload lên object storage
}

